SET NOCOUNT ON;SET XACT_ABORT ON;DECLARE @Lo int=20200140,@Hi int=20200149;INSERT lab.Evidence SELECT o.name,(SELECT COUNT(*) FROM sys.dm_db_column_store_row_group_physical_stats rg WHERE rg.object_id=o.object_id AND rg.state_desc='COMPRESSED'),(SELECT COALESCE(SUM(deleted_rows),0) FROM sys.dm_db_column_store_row_group_physical_stats rg WHERE rg.object_id=o.object_id),(SELECT COUNT(*) FROM sys.column_store_segments s JOIN sys.partitions p ON p.hobt_id=s.hobt_id JOIN sys.columns c ON c.object_id=p.object_id AND c.column_id=s.column_id WHERE p.object_id=o.object_id AND c.name='DateKey'),(SELECT COUNT(*) FROM sys.column_store_segments s JOIN sys.partitions p ON p.hobt_id=s.hobt_id JOIN sys.columns c ON c.object_id=p.object_id AND c.column_id=s.column_id WHERE p.object_id=o.object_id AND c.name='DateKey' AND TRY_CONVERT(int,s.max_data_id)>=@Lo AND TRY_CONVERT(int,s.min_data_id)<=@Hi),0,0 FROM sys.objects o WHERE o.object_id IN(OBJECT_ID(N'lab.OrderedFact'),OBJECT_ID(N'lab.ShuffledFact'));
UPDATE e SET ResultRows=q.RowsFound,ResultSum=q.SumFound FROM lab.Evidence e CROSS APPLY(SELECT COUNT_BIG(*) RowsFound,SUM(CONVERT(bigint,MeasureValue)) SumFound FROM (SELECT DateKey,MeasureValue FROM lab.OrderedFact WHERE e.TableName='OrderedFact' UNION ALL SELECT DateKey,MeasureValue FROM lab.ShuffledFact WHERE e.TableName='ShuffledFact')d WHERE DateKey BETWEEN @Lo AND @Hi)q;PRINT 'SQLPERF_SUMMARY|PASS|OK';
